    <div class="floor-container">
        <!-- Header -->
        <div class="text-center mb-4">
            <h1 class="text-2xl font-bold text-gray-800 mb-1">4th Floor</h1>
            <p class="text-sm text-gray-600">WCC SCAN Campus Directory</p>
        </div>

